DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('private.org_commands(jsonb)'::regprocedure) INTO d;IF d NOT LIKE '%jsonb_array_elements_text(v->''specialty_ids'') x%' THEN RAISE EXCEPTION 'Unexpected specialty validation';END IF;d:=replace(d,$s$jsonb_array_elements_text(v->'specialty_ids') x WHERE NOT EXISTS(SELECT 1 FROM mkt_specialties s WHERE s.id=x$s$,$s$jsonb_array_elements_text(v->'specialty_ids') picked(specialty_id) WHERE NOT EXISTS(SELECT 1 FROM mkt_specialties s WHERE s.id=picked.specialty_id$s$);EXECUTE d;END $$;